class Solution {
public:
    vector<vector<string>> accountsMerge(vector<vector<string>>& accounts) {
        unordered_map<string, string> parent;
        unordered_map<string, string> emailToName;
        auto find = [&](auto self, const string& x) -> string {
            if (parent[x] != x) parent[x] = self(self, parent[x]);
            return parent[x];
        };
        auto unite = [&](const string& x, const string& y) {
            string rx = find(find, x), ry = find(find, y);
            if (rx != ry) parent[rx] = ry;
        };
        for (const auto& acc : accounts) {
            const string& name = acc[0];
            const string& firstEmail = acc[1];
            for (size_t i = 1; i < acc.size(); ++i) {
                const string& email = acc[i];
                if (!parent.count(email)) parent[email] = email;
                emailToName[email] = name;
                unite(firstEmail, email);
            }
        }
        unordered_map<string, vector<string>> groups;
        for (const auto& pair : parent) {
            string root = find(find, pair.first);
            groups[root].push_back(pair.first);
        }
        vector<vector<string>> res;
        for (auto& pair : groups) {
            sort(pair.second.begin(), pair.second.end());
            vector<string> entry = {emailToName[pair.first]};
            entry.insert(entry.end(), pair.second.begin(), pair.second.end());
            res.push_back(entry);
        }
        return res;
    }
};

class Solution {
    public List<List<String>> accountsMerge(List<List<String>> accounts) {
        Map<String, String> parent = new HashMap<>();
        Map<String, String> emailToName = new HashMap<>();
        for (List<String> acc : accounts) {
            String name = acc.get(0);
            String firstEmail = acc.get(1);
            for (int i = 1; i < acc.size(); i++) {
                String email = acc.get(i);
                parent.putIfAbsent(email, email);
                emailToName.put(email, name);
                union(parent, firstEmail, email);
            }
        }
        Map<String, List<String>> groups = new HashMap<>();
        for (String email : parent.keySet()) {
            String root = find(parent, email);
            groups.computeIfAbsent(root, k -> new ArrayList<>()).add(email);
        }
        List<List<String>> res = new ArrayList<>();
        for (Map.Entry<String, List<String>> entry : groups.entrySet()) {
            List<String> emails = entry.getValue();
            Collections.sort(emails);
            List<String> merged = new ArrayList<>();
            merged.add(emailToName.get(entry.getKey()));
            merged.addAll(emails);
            res.add(merged);
        }
        return res;
    }
    private String find(Map<String, String> parent, String x) {
        if (!parent.get(x).equals(x)) {
            parent.put(x, find(parent, parent.get(x)));
        }
        return parent.get(x);
    }
    private void union(Map<String, String> parent, String x, String y) {
        String rx = find(parent, x), ry = find(parent, y);
        if (!rx.equals(ry)) parent.put(rx, ry);
    }
}

var accountsMerge = function(accounts) {
    const parent = new Map();
    const emailToName = new Map();
    const find = (x) => {
        if (parent.get(x) !== x) {
            parent.set(x, find(parent.get(x)));
        }
        return parent.get(x);
    };
    const union = (x, y) => {
        const rx = find(x), ry = find(y);
        if (rx !== ry) parent.set(rx, ry);
    };
    for (const acc of accounts) {
        const name = acc[0];
        const firstEmail = acc[1];
        for (let i = 1; i < acc.length; i++) {
            const email = acc[i];
            if (!parent.has(email)) parent.set(email, email);
            emailToName.set(email, name);
            union(firstEmail, email);
        }
    }
    const groups = new Map();
    for (const email of parent.keys()) {
        const root = find(email);
        if (!groups.has(root)) groups.set(root, []);
        groups.get(root).push(email);
    }
    const res = [];
    for (const [root, emails] of groups.entries()) {
        emails.sort();
        res.push([emailToName.get(root), ...emails]);
    }
    return res;
};
